def count_fastest_routes(n: int, roads: list[list[int]]) -> int:
    adj = [[] for _ in range(n)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))
    best, count = float("inf"), 0
    on_route = [False] * n

    def go(u: int, spent: int) -> None:          # try every route that never repeats a node
        nonlocal best, count
        if spent > best:
            return
        if u == n - 1:
            if spent < best:
                best, count = spent, 0
            count += 1
            return
        on_route[u] = True
        for v, w in adj[u]:
            if not on_route[v]:
                go(v, spent + w)
        on_route[u] = False

    go(0, 0)
    return count
